function analyze(){check();if(imported)throw Error('此批已匯入，請查看庫存或選擇新的檔案。');if(!groups.length)throw Error('至少需要一組欄位。');const used=new Set();for(const g of groups){if(g.name<0||g.quantity<0)throw Error('每組都必須選擇品項欄與數量欄。');const fields=Object.values(g).filter(c=>c>=0);if(new Set(fields).size!==fields.length)throw Error('同一組不可將同一欄對應至不同欄位。');for(const c of fields){if(used.has(c))throw Error('不同組不可重複使用同一來源欄。');used.add(c);}}rows=[];const sh=sheet(),h=Number($('siHeader').value)-1;for(let ri=h+1;ri<sh.matrix.length;ri++){const source=sh.matrix[ri]||[];for(const g of groups){const r={location:norm(source[g.location]),name:norm(source[g.name]),quantity:norm(source[g.quantity]),unit:norm(source[g.unit]),source:sh.name+'!'+col(g.name)+(ri+1),originalRow:ri+1,group:groups.indexOf(g)};if(!r.name&&!r.quantity&&!r.location&&!r.unit)continue;if(kind(r.name)==='name'&&kind(r.quantity)==='quantity')continue;rows.push(r);}}if(rows.length>20000)throw Error('整理後超過 20,000 筆，請拆分。');duplicates();batchId=crypto.randomUUID();imported=false;selectedGroup='all';page=0;$('siMapping').open=false;$('siResult').hidden=false;render();$('siStatus').textContent='整理完成，共 '+rows.length+' 筆。尚未儲存；可先儲存草稿，核對完成後再確認匯入。';}
