 for(const id of ['all',...groups.map((g,i)=>String(i))]){const subset=id==='all'?rows:rows.filter(r=>r.group===Number(id)),button=el('button',(id==='all'?'全部':groupLabel(Number(id)))+' · '+subset.length,'btn');button.type='button';button.setAttribute('aria-pressed',String(selectedGroup===id));button.onclick=()=>{selectedGroup=id;page=0;render();};tabs.append(button);}
