function resumeDraft(){if(!authorized())throw Error('目前帳號沒有標籤與匯入權限。');const d=readDraft();if(!d)throw Error('沒有可繼續的草稿。');if(rows.length&&!window.confirm('載入草稿會取代畫面上尚未儲存的預覽。確定繼續？'))return;++epoch;workingOwner=ownerScope();sheets=d.sheets.map(s=>({...s,matrix:s.matrix.map(r=>r||[])}));groups=d.groups;rows=d.rows;fileName=d.fileName;sourceHash=d.sourceHash;batchId=d.batchId;const priorBatches=readInventory().batches.filter(b=>b.sourceKey===sourceHash+':'+d.selectedSheet);imported=priorBatches.some(b=>b.partial!==true);if(!imported&&priorBatches.length){const done=new Set(priorBatches.flatMap(b=>b.rows.map(sourceRowIdentity)));rows=rows.filter(r=>!done.has(sourceRowIdentity(r)));imported=!rows.length;}$('siFile').value='';$('siSheet').replaceChildren(...sheets.map((s,i)=>new Option(s.name,String(i))));$('siSheet').value=String(d.selectedSheet);$('siHeader').value=String(d.header);$('siSetup').hidden=false;$('siResult').hidden=false;$('siAdvanced').open=false;$('siMapping').open=false;selectedGroup='all';page=0;duplicates();mapping();render();refreshDraftInfo();$('siStatus').textContent=imported?'這份草稿所屬的批次已匯入，請查看庫存，不能再次匯入。':'已載入草稿，共 '+rows.length+' 筆。修改後請再次儲存草稿。';}
const sourceRowIdentity=r=>JSON.stringify([r.group,r.originalRow]);
const stockIdentity=r=>JSON.stringify([norm(r.location).normalize('NFKC').toLocaleLowerCase(),norm(r.name).normalize('NFKC').toLocaleLowerCase()]);
