 const definitions=setupDefinitions(data).map(d=>({...d}));let affected=0;for(const batch of data.batches)for(const row of batch.rows)if(row.warehouse===target.warehouse&&row.location===target.location){row.location=name;affected++;}for(const d of definitions)if(d.warehouse===target.warehouse&&d.location===target.location)d.location=name;definitions.push({warehouse:target.warehouse,location:name});
 const identities=new Set();for(const batch of data.batches)for(const row of batch.rows){const identity=stockIdentity(row);if(identities.has(identity))throw Error('修改後會出現同位置、同品項的重複資料，請改用其他名稱。');identities.add(identity);}if(data.locationSettingHistory!==undefined&&!Array.isArray(data.locationSettingHistory))throw Error('設定異動紀錄格式不正確，原資料已保留。');const p=actor();data.locationSettings=[...new Map(definitions.map(d=>[JSON.stringify([d.warehouse,d.location]),d])).values()];data.locationSettingHistory=[...(data.locationSettingHistory||[]),{at:new Date().toISOString(),actorId:p.id,actorName:p.name||p.account||'操作人員',action:'renameLocation',before:{warehouse:target.warehouse,location:target.location},after:name,affectedRows:affected}];writeLocal(key,JSON.stringify(data));target.location=name;target.raw=localStorage.getItem(key);renderSettings();positionMode(false);sp('spNote').textContent='已儲存位置名稱，共 '+target.count+' 筆品項，數量不變。';sp('spEdit').focus();
