sp('spEdit').onclick=()=>{if(positionTarget?.location&&settingsAuthorized())positionMode(true);};sp('spCancel').onclick=()=>{if(!positionSaving)positionMode(false);};sp('spSave').onclick=savePositionName;sp('spX').onclick=sp('spClose').onclick=()=>{if(!positionSaving)positionDialog.close();};positionDialog.addEventListener('cancel',event=>{if(positionSaving)event.preventDefault();});positionDialog.addEventListener('close',()=>{const trigger=positionTarget?.trigger;positionTarget=null;trigger?.focus();});
