// Internal warehouse transfers: applications and review do not mutate inventory rows.
const transferRoot=el('section');transferRoot.id='siTransfers';transferRoot.hidden=true;document.getElementById('module').append(transferRoot);
transferRoot.innerHTML='<div class="st-panel"><h2>新增庫存移轉</h2><p>倉庫內換位置使用移轉；從倉庫領到 N櫃或現場使用位置，請使用領用。</p><p>申請 → 主管審核 → 現場執行</p><p class="st-note">目前先提供同一倉別內的移轉申請與審核。核准後為待執行，尚不變更庫存；標籤綁定與掃描執行將接續加入。</p><label>搜尋品項<input id="stSearch" type="search" placeholder="輸入品項或原位置"></label><label>選擇品項<select id="stItem"></select></label><div class="st-fields"><span>原倉別</span><span id="stWarehouse" class="st-readonly"></span><span>原位置</span><span id="stLocation" class="st-readonly"></span><span>目前數量</span><span id="stQuantity" class="st-readonly"></span><label for="stAmount">申請移轉數量</label><input id="stAmount" inputmode="decimal" autocomplete="off"><label for="stDestination">目標位置</label><select id="stDestination"></select><label for="stReason">移轉原因</label><textarea id="stReason" maxlength="500" rows="3"></textarea></div><p id="stError" role="alert"></p><p id="stStatus" role="status" aria-live="polite"></p><div class="st-actions"><button id="stSubmit" class="btn" type="button">送出申請</button></div></div><div class="st-panel"><div class="st-head"><h2>移轉申請紀錄</h2><button class="btn" id="stRefresh" type="button">重新讀取</button></div><div class="st-scroll"><div id="stRequests" class="st-record-list" aria-live="polite"></div></div><div class="st-actions"><button class="btn" id="stPrev">上一頁</button><span id="stPage"></span><button class="btn" id="stNext">下一頁</button></div></div>';
const st=id=>transferRoot.querySelector('#'+id);let transferPage=0,transferBusy=false,transferScope='',transferSelections=[];
function transferUser(){const p=Workspace.current();if(!p||!p.systems.includes('WMS')||!p.permissions.includes('stock')||!p.permissions.some(x=>['returns','dispatch','approve'].includes(x)))throw Error('目前帳號需要庫存查詢與歸還移轉、工作派送或審核權限。');return p;}
function transferReviewer(){try{const p=transferUser();return ['sm','executive'].includes(Workspace.role(p))&&p.permissions.some(x=>['approve','dispatch'].includes(x));}catch{return false;}}
function transferRequests(data){const list=data.transferRequests??[];if(!Array.isArray(list)||list.some(r=>!r||typeof r.id!=='string'||!['待審核','已駁回','待執行','已取消'].includes(r.status)||typeof r.name!=='string'||typeof r.warehouse!=='string'||typeof r.from!=='string'||typeof r.to!=='string'||typeof r.actorId!=='string'||typeof r.reason!=='string'||!Number.isFinite(r.amount)||r.amount<=0))throw Error('移轉單據格式不正確，原資料已保留。');return list;}
function transferSource(data,token){const pair=JSON.parse(token||'null');if(!Array.isArray(pair)||pair.length!==2)throw Error('請選擇品項。');const batch=data.batches.find(b=>b.id===pair[0]),row=batch?.rows.find(r=>r.id===pair[1]);if(!row)throw Error('品項已變更，請重新選取。');return {batch,row};}
function renderTransferSource(){try{transferUser();const data=readInventory(),{row}=transferSource(data,st('stItem').value);st('stWarehouse').textContent=row.warehouse;st('stLocation').textContent=row.location||'位置待確認';st('stQuantity').textContent=norm(row.quantity)===''?'待確認':row.quantity+(row.unit?' '+row.unit:'');const previous=st('stDestination').value,positions=setupGroups(data).get(row.warehouse)||new Map();st('stDestination').replaceChildren(new Option('請選擇同倉別目標位置',''),...[...positions.keys()].filter(x=>x&&x!==row.location).sort(locationCompare).map(x=>new Option(x,x)));if(positions.has(previous)&&previous!==row.location)st('stDestination').value=previous;else st('stDestination').value='';st('stSubmit').disabled=transferBusy||!row.location||row.quantityValue===null||row.quantityValue<=0;if(!row.location)st('stError').textContent='請先在庫存查詢補齊原位置，再建立移轉申請。';else if(row.quantityValue===null||row.quantityValue<=0)st('stError').textContent='數量待確認或為 0，不能建立移轉申請。';else st('stError').textContent='';}catch(error){for(const id of ['stWarehouse','stLocation','stQuantity'])st(id).textContent='—';st('stDestination').replaceChildren(new Option('請先選擇品項',''));st('stSubmit').disabled=true;st('stError').textContent=error.message;}}
function renderTransfers(){try{const p=transferUser();if(transferScope!==ownerScope()){transferScope=ownerScope();transferPage=0;st('stSearch').value='';st('stAmount').value='';st('stReason').value='';st('stStatus').textContent='';}const data=readInventory(),q=norm(st('stSearch').value).toLocaleLowerCase(),previous=st('stItem').value;transferSelections=data.batches.flatMap(b=>b.rows.map(r=>({token:JSON.stringify([b.id,r.id]),row:r}))).filter(x=>!q||(x.row.name+' '+x.row.warehouse+' '+x.row.location).toLocaleLowerCase().includes(q));st('stItem').replaceChildren(new Option('請選擇品項與原位置',''),...transferSelections.map(x=>new Option(x.row.name+' ／ '+x.row.warehouse+' ／ '+(x.row.location||'位置待確認'),x.token)));st('stItem').value=transferSelections.some(x=>x.token===previous)?previous:'';renderTransferSource();const requests=[...transferRequests(data)].reverse(),max=Math.max(1,Math.ceil(requests.length/30));transferPage=Math.max(0,Math.min(transferPage,max-1));const body=st('stRequests');body.replaceChildren();for(const r of requests.slice(transferPage*30,transferPage*30+30)){
 const card=el('article',undefined,'st-record-card'),head=el('div',undefined,'st-record-head'),status=el('span',r.status,'st-record-status');
 status.dataset.status=r.status;head.append(el('strong',r.number||'移轉申請'),status);
 const content=el('div',undefined,'st-record-content'),summary=el('div',undefined,'st-record-summary');
 summary.append(el('strong',r.name+' · '+String(r.amount)+(r.unit?' '+r.unit:'')),el('p',r.warehouse+'／'+r.from+' → '+r.to,'st-record-route'),el('p','申請人 '+(r.actorName||'—')+' · '+new Date(r.createdAt).toLocaleString('zh-TW'),'st-record-meta'),el('p',r.reason,'st-record-reason'));
 const actions=el('div',undefined,'st-record-actions'),details=el('button','查看詳情','btn');details.type='button';details.onclick=()=>openTransferDetails(r.id);actions.append(details);
 if(r.status==='待審核'&&transferReviewer()){for(const action of ['核准','駁回']){const button=el('button',action,'btn');button.type='button';button.dataset.action=action;button.onclick=()=>openTransferReview(r.id,action);actions.append(button);}}
 if(['待審核','待執行'].includes(r.status)&&(r.actorId===p.id||transferReviewer())){const button=el('button','取消申請','btn');button.type='button';button.onclick=()=>openTransferReview(r.id,'取消');actions.append(button);}
 content.append(summary,actions);card.append(head,content);
 if(r.status==='待執行')card.append(el('p','待綁定標籤與接入掃描執行，庫存未變更。','st-record-meta'));
 if(r.reviewReason)card.append(el('p','審核說明：'+r.reviewReason,'st-record-reason'));
 body.append(card);
}if(!requests.length)body.append(el('div','尚無移轉申請。','sr-record-empty'));st('stPage').textContent='第 '+(transferPage+1)+' / '+max+' 頁';st('stPrev').disabled=transferPage===0;st('stNext').disabled=transferPage===max-1;}catch(error){st('stRequests').replaceChildren();st('stSubmit').disabled=true;st('stError').textContent=error.message;}}
async function submitTransfer(){if(transferBusy)return;transferBusy=true;st('stSubmit').disabled=true;st('stError').textContent='';try{const p=transferUser(),scope=ownerScope(),token=st('stItem').value,to=norm(st('stDestination').value),reason=norm(st('stReason').value),rawAmount=norm(st('stAmount').value);if(!/^(?:\d+)(?:\.\d+)?$/.test(rawAmount))throw Error('請填寫大於 0 的移轉數量。');const amount=Number(rawAmount);if(!Number.isFinite(amount)||amount<=0||amount>Number.MAX_SAFE_INTEGER)throw Error('請填寫有效的移轉數量。');if(!reason||reason.length>500)throw Error('請填寫移轉原因，最多 500 字。');const key=inventoryKey();await locked(key,()=>{transferUser();if(ownerScope()!==scope)throw Error('登入身分已變更，請重新填寫。');const data=readInventory(),{batch,row}=transferSource(data,token),positions=setupGroups(data).get(row.warehouse);if(!row.location||!to||to===row.location||!positions?.has(to))throw Error('請選擇同倉別內不同的已建立位置。');if(row.quantityValue===null||amount>row.quantityValue)throw Error('申請數量超過目前數量，或目前數量尚未確認。');const list=transferRequests(data);if(list.some(r=>r.batchId===batch.id&&r.rowId===row.id&&['待審核','待執行'].includes(r.status)))throw Error('此筆庫存已有未完成移轉單，請先處理原單，避免重複申請。');const id=crypto.randomUUID(),at=new Date().toISOString();data.transferRequests=[...list,{id,number:'TR-'+id.slice(0,8).toUpperCase(),createdAt:at,status:'待審核',actorId:p.id,actorName:p.name||p.account||'操作人員',batchId:batch.id,rowId:row.id,name:row.name,warehouse:row.warehouse,from:row.location,to,unit:row.unit,amount,reason,sourceSnapshot:JSON.stringify(row),history:[{action:'建立申請',at,actorId:p.id}]}];writeLocal(key,JSON.stringify(data));});st('stAmount').value='';st('stReason').value='';st('stStatus').textContent='已送出移轉申請，等待主管審核；庫存數量與位置未變更。';renderTransfers();}catch(error){st('stError').textContent=error.message;}finally{transferBusy=false;const message=st('stError').textContent;renderTransferSource();if(message)st('stError').textContent=message;}}
const transferReview=el('dialog');transferReview.id='stReviewDialog';transferReview.innerHTML='<h2 id="strTitle"></h2><p id="strSummary"></p><label>原因／說明<textarea id="strReason" maxlength="500" rows="3"></textarea></label><p id="strError" role="alert"></p><div class="st-actions"><button class="btn" id="strCancel">返回</button><button class="btn" id="strSave">確認</button></div>';document.body.append(transferReview);const str=id=>transferReview.querySelector('#'+id);let transferReviewTarget=null;
function openTransferReview(id,action){try{const p=transferUser(),r=transferRequests(readInventory()).find(r=>r.id===id);if(!r)throw Error('找不到移轉單。');if(action!=='取消'&&!transferReviewer())throw Error('只有具權限的 SM／高階主管可審核。');if(action==='取消'&&r.actorId!==p.id&&!transferReviewer())throw Error('只有建立者或主管可取消。');transferReviewTarget={id,action,scope:ownerScope(),snapshot:JSON.stringify(r)};str('strTitle').textContent=action+'移轉申請';str('strSummary').textContent=r.name+' ／ '+r.warehouse+'／'+r.from+' → '+r.to+' ／ 數量 '+r.amount;str('strReason').value='';str('strError').textContent='';transferReview.showModal();}catch(error){st('stError').textContent=error.message;}}
